    unsigned long long seed = training ? std::rand() : 0;
    float scale = training ? 1.0f / (1.0f - dropout_p) : 1.0f;

    dropout_softmax_forward_kernel<<<batch_size, threads, shared_mem>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_features,
        dropout_p,
        scale,
        seed,
