    float scale_factor
) {
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;
    int block_size = blockDim.x;

    // Each thread computes partial sum of max-pooled values
    const float* row = input + batch_idx * out_features;

    // Number of pairs for maxpool with kernel_size=2
    int num_pairs = out_features / 2;

    float local_sum = 0.0f;

    // Each thread processes multiple pairs
    for (int i = tid; i < num_pairs; i += block_size) {
        float a = row[2 * i];
        float b = row[2 * i + 1];
        float max_val = (a > b) ? a : b;
        local_sum += max_val;
    }

    // Warp-level reduction using shuffle
    __shared__ float shared_sum[32];  // One entry per warp

    // Warp reduce
    for (int offset = 32; offset > 0; offset /= 2) {
        local_sum += __shfl_down(local_sum, offset);
