instance_norm_divide_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

// Warp reduction for sum
__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 32; offset > 0; offset >>= 1) {
        val += __shfl_down(val, offset);
    }
    return val;
}

// Block reduction using shared memory
__device__ float block_reduce_sum(float val, float* shared) {
    int lane = threadIdx.x % 64;
    int wid = threadIdx.x / 64;

    // Warp-level reduction
    for (int offset = 32; offset > 0; offset >>= 1) {
        val += __shfl_down(val, offset);
    }

    // Write reduced warp values to shared memory
    if (lane == 0) {
        shared[wid] = val;
    }
    __syncthreads();

    // Final reduction in first warp
    int num_warps = (blockDim.x + 63) / 64;
    val = (threadIdx.x < num_warps) ? shared[threadIdx.x] : 0.0f;

    if (wid == 0) {
        for (int offset = 32; offset > 0; offset >>= 1) {
            val += __shfl_down(val, offset);
        }
    }

    return val;
}

// Fused InstanceNorm + Divide kernel
// Each block handles one (batch, channel) pair
__global__ void instance_norm_divide_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int height,
    int width,
    float divide_by,
    float eps
) {
    // Each block processes one (n, c) pair
    int nc = blockIdx.x;
    int n = nc / channels;
    int c = nc % channels;

    if (n >= batch_size) return;

    int spatial_size = height * width;
    const float* in_ptr = input + (n * channels + c) * spatial_size;
    float* out_ptr = output + (n * channels + c) * spatial_size;

    __shared__ float shared_mem[32];  // For block reduction

    // Compute mean using parallel reduction
    float sum = 0.0f;
    for (int i = threadIdx.x; i < spatial_size; i += blockDim.x) {
        sum += in_ptr[i];
    }

    // Block reduce
    int lane = threadIdx.x % 64;
    int wid = threadIdx.x / 64;

    for (int offset = 32; offset > 0; offset >>= 1) {
        sum += __shfl_down(sum, offset);
    }

    if (lane == 0) {
        shared_mem[wid] = sum;
    }
    __syncthreads();

    int num_warps = (blockDim.x + 63) / 64;
    sum = (threadIdx.x < num_warps) ? shared_mem[threadIdx.x] : 0.0f;

    if (wid == 0) {
        for (int offset = 32; offset > 0; offset >>= 1) {
            sum += __shfl_down(sum, offset);
        }
    }

    __shared__ float mean_shared;
    if (threadIdx.x == 0) {
        mean_shared = sum / spatial_size;
    }
    __syncthreads();
    float mean = mean_shared;

    // Compute variance
    float var_sum = 0.0f;
    for (int i = threadIdx.x; i < spatial_size; i += blockDim.x) {
        float diff = in_ptr[i] - mean;
        var_sum += diff * diff;
    }

    // Block reduce variance
    for (int offset = 32; offset > 0; offset >>= 1) {
        var_sum += __shfl_down(var_sum, offset);
    }

    if (lane == 0) {
        shared_mem[wid] = var_sum;
    }
    __syncthreads();

    var_sum = (threadIdx.x < num_warps) ? shared_mem[threadIdx.x] : 0.0f;

    if (wid == 0) {
        for (int offset = 32; offset > 0; offset >>= 1) {
            var_sum += __shfl_down(var_sum);
        }
    }

    __shared__ float inv_std_shared;
    if (threadIdx.x == 0) {
        float var = var_sum / spatial_size;
        inv_std_shared = rsqrtf(var + eps) / divide_by;
    }
    __syncthreads();
    float inv_std_div = inv_std_shared;

    // Normalize and divide
    for (int i = threadIdx.x; i < spatial_size; i += blockDim.x) {
        out_ptr[i] = (in_ptr[i] - mean) * inv_std_div;
    }
}

