dropout_softmax_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <hiprand_kernel.h>

#define WARP_SIZE 64
#define BLOCK_SIZE 256

// Warp-level reduction for max
__device__ __forceinline__ float warp_reduce_max(float val) {
    #pragma unroll
    for (int offset = WARP_SIZE/2; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_xor(val, offset));
    }
    return val;
}

// Warp-level reduction for sum
__device__ __forceinline__ float warp_reduce_sum(float val) {
    #pragma unroll
    for (int offset = WARP_SIZE/2; offset > 0; offset /= 2) {
        val += __shfl_xor(val, offset);
    }
    return val;
}

// Fused dropout + softmax kernel
__global__ void dropout_softmax_forward_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int batch_size,
    const int num_features,
    const float dropout_p,
    const float scale,
    const unsigned long long seed,
    const bool training
) {
    const int row = blockIdx.x;
    if (row >= batch_size) return;

    const int tid = threadIdx.x;
    const int lane_id = tid % WARP_SIZE;
    const int warp_id = tid / WARP_SIZE;
    const int num_warps = BLOCK_SIZE / WARP_SIZE;

    const float* row_input = input + row * num_features;
    float* row_output = output + row * num_features;

    __shared__ float warp_max[BLOCK_SIZE / WARP_SIZE];
    __shared__ float warp_sum[BLOCK_SIZE / WARP_SIZE];

    // Initialize random state for this thread
    hiprandStatePhilox4_32_10_t state;
    if (training) {
        hiprand_init(seed, (unsigned long long)(row * num_features + tid), 0, &state);
    }

    // First pass: find max value (with dropout applied)
    float thread_max = -INFINITY;

    for (int i = tid; i < num_features; i += BLOCK_SIZE) {
        float val = row_input[i];

        if (training) {
            float rand_val = hiprand_uniform(&state);
            if (rand_val < dropout_p) {
                val = 0.0f;
            } else {
                val = val * scale;
            }
        }
        thread_max = fmaxf(thread_max, val);
    }

    // Warp reduction for max
    float warp_max_val = warp_reduce_max(thread_max);
    if (lane_id == 0) {
        warp_max[warp_id] = warp_max_val;
    }
    __syncthreads();

    // Final reduction across warps
    float global_max;
    if (tid < num_warps) {
        global_max = warp_max[tid];
    } else {
        global_max = -INFINITY;
    }
    global_max = warp_reduce_max(global_max);
    __syncthreads();

    // Re-initialize random state for second pass
    if (training) {
        hiprand_init(seed, (unsigned long long)(row * num_features + tid), 0, &state);
    }

    // Second pass: compute sum of exp(x - max)
    float thread_sum = 0.0f;

    for (int i = tid; i < num_features; i += BLOCK_SIZE) {
        float val = row_input[i];

        if (training) {
            float rand_val = hiprand_uniform(&state);
            if (rand_val < dropout_p) {
                val = 0.0f;
            } else {
                val = val * scale;
            }
        }
        thread_sum += expf(val - global_max);
    }

    // Warp reduction for sum
    float warp_sum_val = warp_reduce_sum(thread_sum);
    if (lane_id == 0) {
        warp_sum[warp_id] = warp_sum_val;
    }
    __syncthreads();

    // Final reduction across warps
    float global_sum;
    if (tid < num_warps) {
        global_sum = warp_sum[tid];
    } else {
        global_sum = 0.0f;
    }
    global_sum = warp_reduce_sum(global_sum);

    float inv_sum = 1.0f / global_sum;

    // Re-initialize random state for third pass
    if (training) {
        hiprand_init(seed, (unsigned long long)(row * num_features + tid), 0, &state);
    }

    // Third pass: compute final softmax output
    for (int i = tid; i < num_features; i += BLOCK_SIZE) {
        float val = row_input[i];

        if (training) {
            float rand_val = hiprand_uniform(&state);
            if (rand_val < dropout_p) {
                val = 0.0f;
            } else {
                val = val * scale;
            }
        }
        row_output[i] = expf(val - global_max) * inv_sum;
    }
}

torch::Tensor dropout_softmax_forward(
    torch::Tensor input,
    float dropout_p,
    bool training
) {
    const int batch_size = input.size(0);
    const int num_features = input.size(1);

    auto output = torch::empty_like(input);

    // Generate random seed
    unsigned long long seed = training ? (unsigned long long)std::rand() : 0;
    float scale = training ? 1.0f / (1.0f - dropout_p) : 1.0f;

    dropout_softmax_forward_kernel<<<batch_size, BLOCK_SIZE>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        num_features,
        dropout_p,
        scale,
        seed,
        training
    );

    return output;
}
