# This avoids writing intermediate results to memory
fused_maxpool_sum_scale_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Fused kernel: MaxPool1d (kernel_size=2) + Sum + Scale
// Each block handles one row of the input
__global__ void fused_maxpool_sum_scale_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int out_features,
    float scale_factor
) {
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;
    int block_size = blockDim.x;

    // Each thread computes partial sum of max-pooled values
    const float* row = input + batch_idx * out_features;

    // Number of pairs for maxpool with kernel_size=2
    int num_pairs = out_features / 2;

    float local_sum = 0.0f;

    // Each thread processes multiple pairs
    for (int i = tid; i < num_pairs; i += block_size) {
        float a = row[2 * i];
        float b = row[2 * i + 1];
        float max_val = (a > b) ? a : b;
        local_sum += max_val;
    }

    // Use shared memory for block reduction
    __shared__ float shared_data[256];
    shared_data[tid] = local_sum;
    __syncthreads();

    // Block reduction in shared memory
    for (int s = block_size / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }

    // Thread 0 writes final result
    if (tid == 0) {
        output[batch_idx] = shared_data[0] * scale_factor;
    }
}

