#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

#define WARP_SIZE 64
#define BLOCK_SIZE 1024

__device__ __forceinline__ float gelu(float x) {
    // GELU(x) = x * 0.5 * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
    const float sqrt_2_over_pi = 0.7978845608028654f;
    const float coeff = 0.044715f;
    float x3 = x * x * x;
    float inner = sqrt_2_over_pi * (x + coeff * x3);
    return 0.5f * x * (1.0f + tanhf(inner));
}

// Warp reduction for max
__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_down(val, offset));
    }
    return val;
}

// Warp reduction for sum
__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

// Two-pass online softmax with fused GELU - compute max and exp-sum in passes
__global__ void fused_gelu_softmax_kernel(const float* __restrict__ input, 
                                           float* __restrict__ output,
                                           int batch_size, int features) {
    // Each block handles one row
    int row = blockIdx.x;
    if (row >= batch_size) return;

    const float* row_in = input + row * features;
    float* row_out = output + row * features;

    int tid = threadIdx.x;
    int num_threads = blockDim.x;
    int warp_id = tid / WARP_SIZE;
    int lane_id = tid % WARP_SIZE;
    int num_warps = num_threads / WARP_SIZE;

    __shared__ float shared_max[BLOCK_SIZE / WARP_SIZE];
    __shared__ float shared_sum[BLOCK_SIZE / WARP_SIZE];

    // First pass: compute GELU and find max using online approach
    float local_max = -3.402823466e+38f;  // Use -FLT_MAX instead of -INFINITY

    #pragma unroll 4
    for (int i = tid; i < features; i += num_threads) {
        float val = gelu(row_in[i]);
        local_max = fmaxf(local_max, val);
    }

    // Warp reduce max
    local_max = warp_reduce_max(local_max);
    if (lane_id == 0) {
        shared_max[warp_id] = local_max;
    }
    __syncthreads();

    // Final reduction for max across warps
    if (warp_id == 0) {
        float val = (lane_id < num_warps) ? shared_max[lane_id] : -3.402823466e+38f;
        val = warp_reduce_max(val);
        if (lane_id == 0) {
            shared_max[0] = val;
        }
    }
    __syncthreads();

    float row_max = shared_max[0];

    // Second pass: compute exp(gelu(x) - max) and sum
    float local_sum = 0.0f;

    #pragma unroll 4
    for (int i = tid; i < features; i += num_threads) {
        float val = gelu(row_in[i]);
        float exp_val = expf(val - row_max);
        row_out[i] = exp_val;  // Store temporarily
        local_sum += exp_val;
    }

    // Warp reduce sum
    local_sum = warp_reduce_sum(local_sum);
    if (lane_id == 0) {
        shared_sum[warp_id] = local_sum;
    }
    __syncthreads();

    // Final reduction for sum across warps
    if (warp_id == 0) {
        float val = (lane_id < num_warps) ? shared_sum[lane_id] : 0.0f;
        val = warp_reduce_sum(val);
        if (lane_id == 0) {
            shared_sum[0] = val;
        }
    }
    __syncthreads();

    float inv_sum = 1.0f / shared_sum[0];

    // Third pass: normalize
    #pragma unroll 4
    for (int i = tid; i < features; i += num_threads) {
        row_out[i] *= inv_sum;
    }
}

