    int H = input.size(2);
    int W = input.size(3);
    int HW = H * W;

    auto output = torch::empty_like(input);

    int num_nc_pairs = N * C;

    // Use 512 threads per block for good occupancy on MI300X
    fused_bn_scale_kernel_v4<<<num_nc_pairs, BLOCK_SIZE>>>(
        input.data_ptr<float>(),
