# Fused GELU + Softmax kernel - cache GELU in registers/shared mem
fused_gelu_softmax_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

#define WARP_SIZE 64
#define BLOCK_SIZE 256
#define ITEMS_PER_THREAD 32

__device__ __forceinline__ float gelu(float x) {
    const float sqrt_2_over_pi = 0.7978845608028654f;
    const float coeff = 0.044715f;
    float x3 = x * x * x;
    float inner = sqrt_2_over_pi * (x + coeff * x3);
    return 0.5f * x * (1.0f + tanhf(inner));
}

__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_down(val, offset));
    }
    return val;
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

// This kernel uses multiple blocks per row for very large rows
__global__ void fused_gelu_softmax_kernel(const float* __restrict__ input, 
                                           float* __restrict__ output,
                                           int batch_size, int features) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    const float* row_in = input + row * features;
    float* row_out = output + row * features;

    int tid = threadIdx.x;
    int num_threads = blockDim.x;
    int warp_id = tid / WARP_SIZE;
    int lane_id = tid % WARP_SIZE;
    int num_warps = num_threads / WARP_SIZE;

    __shared__ float shared_max[BLOCK_SIZE / WARP_SIZE];
    __shared__ float shared_sum[BLOCK_SIZE / WARP_SIZE];

    // Use register array to cache GELU values
    float gelu_cache[ITEMS_PER_THREAD];

    // Calculate how many items this thread handles
    int items_per_thread_actual = (features + num_threads - 1) / num_threads;

    // First pass: compute GELU values and find max
    float local_max = -3.402823466e+38f;

    for (int j = 0; j < items_per_thread_actual; j++) {
        int i = tid + j * num_threads;
        if (i < features) {
            float val = gelu(row_in[i]);
            if (j < ITEMS_PER_THREAD) {
                gelu_cache[j] = val;
            }
            local_max = fmaxf(local_max, val);
        }
    }

    // Warp reduce max
    local_max = warp_reduce_max(local_max);
    if (lane_id == 0) {
        shared_max[warp_id] = local_max;
    }
    __syncthreads();

    if (warp_id == 0) {
        float val = (lane_id < num_warps) ? shared_max[lane_id] : -3.402823466e+38f;
        val = warp_reduce_max(val);
        if (lane_id == 0) {
            shared_max[0] = val;
        }
    }
    __syncthreads();

    float row_max = shared_max[0];

    // Second pass: compute exp values and sum using cached GELU
    float local_sum = 0.0f;

    for (int j = 0; j < items_per_thread_actual; j++) {
        int i = tid + j * num_threads;
        if (i < features) {
            float val;
            if (j < ITEMS_PER_THREAD) {
                val = gelu_cache[j];
            } else {
                val = gelu(row_in[i]);
            }
            float exp_val = expf(val - row_max);
            row_out[i] = exp_val;
            local_sum += exp_val;
        }
    }

    // Warp reduce sum
    local_sum = warp_reduce_sum(local_sum);
    if (lane_id == 0) {
        shared_sum[warp_id] = local_sum;
    }
    __syncthreads();

    if (warp_id == 0) {
        float val = (lane_id < num_warps) ? shared_sum[lane_id] : 0.0f;
        val = warp_reduce_sum(val);
        if (lane_id == 0) {
            shared_sum[0] = val;
        }
    }
    __syncthreads();

    float inv_sum = 1.0f / shared_sum[0];

    // Third pass: normalize
    for (int j = 0; j < items_per_thread_actual; j++) {
        int i = tid + j * num_threads;
        if (i < features) {
            row_out[i] *= inv_sum;
        }
    }
}

torch::Tensor fused_gelu_softmax_hip(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 2, "Input must be 2D");

    int batch_size = input.size(0);
    int features = input.size(1);

    auto output = torch::empty_like(input);

    dim3 grid(batch_size);
    dim3 block(BLOCK_SIZE);

    fused_gelu_softmax_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        features
    );

    return output;
}
