    int block_size = 256;
    int num_blocks = batch_size;

    fused_bias_div_gelu_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        divisor_inv,
        batch_size,
