# Fused kernel for MaxPool1d + Sum + Scale
# This avoids writing intermediate results to memory
fused_maxpool_sum_scale_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Fused kernel: MaxPool1d (kernel_size=2) + Sum + Scale
// Each block handles one row of the input, using vectorized loads
__global__ void fused_maxpool_sum_scale_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int out_features,
    float scale_factor
) {
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;
    int block_size = blockDim.x;

    // Each thread computes partial sum of max-pooled values
    const float* row = input + batch_idx * out_features;

    // Number of pairs for maxpool with kernel_size=2
    int num_pairs = out_features / 2;

    float local_sum = 0.0f;

    // Use float4 for vectorized loads (loads 4 floats = 2 pairs at once)
    const float4* row4 = reinterpret_cast<const float4*>(row);
    int num_float4 = num_pairs / 2;  // Each float4 contains 2 pairs

    // Each thread processes multiple float4s
    for (int i = tid; i < num_float4; i += block_size) {
        float4 v = row4[i];
        // v.x and v.y form pair 1, v.z and v.w form pair 2
        float max1 = (v.x > v.y) ? v.x : v.y;
        float max2 = (v.z > v.w) ? v.z : v.w;
        local_sum += max1 + max2;
    }

    // Handle remaining pairs if num_pairs is not divisible by 2
    int remaining_start = num_float4 * 2;
    for (int i = remaining_start + tid; i < num_pairs; i += block_size) {
        float a = row[2 * i];
        float b = row[2 * i + 1];
        local_sum += (a > b) ? a : b;
    }

    // Use shared memory for block reduction
    __shared__ float shared_data[1024];
    shared_data[tid] = local_sum;
    __syncthreads();

    // Block reduction in shared memory
    for (int s = block_size / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }

    // Thread 0 writes final result
    if (tid == 0) {
        output[batch_idx] = shared_data[0] * scale_factor;
    }
}

torch::Tensor fused_maxpool_sum_scale_hip(torch::Tensor input, float scale_factor) {
    int batch_size = input.size(0);
    int out_features = input.size(1);

    auto output = torch::empty({batch_size}, input.options());

    // Use larger block size for better occupancy
    int block_size = 1024;
    int num_blocks = batch_size;

    fused_maxpool_sum_scale_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        out_features,
        scale_factor
    );

    return output;
}
