    // Warp reduction (AMD wavefront = 64)
    for (int offset = 32; offset > 0; offset >>= 1) {
        local_max = fmaxf(local_max, __shfl_down(local_max, offset));
    }

    __shared__ float warp_maxes[16];

    int lane = tid & 63;
    int warp_id = tid >> 6;

    if (lane == 0) {
        warp_maxes[warp_id] = local_max;
