#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

#define WARP_SIZE 64
#define BLOCK_SIZE 256

__device__ __forceinline__ float gelu(float x) {
    const float sqrt_2_over_pi = 0.7978845608028654f;
    const float coeff = 0.044715f;
    float x3 = x * x * x;
    float inner = sqrt_2_over_pi * (x + coeff * x3);
    return 0.5f * x * (1.0f + tanhf(inner));
}

__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_down(val, offset));
    }
    return val;
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = WARP_SIZE / 2; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset);
    }
    return val;
}

// Vectorized kernel using float4
__global__ void fused_gelu_softmax_kernel_vec4(const float4* __restrict__ input, 
                                                float4* __restrict__ output,
                                                int batch_size, int features) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    int vec_features = features / 4;
    const float4* row_in = input + row * vec_features;
    float4* row_out = output + row * vec_features;

    int tid = threadIdx.x;
    int num_threads = blockDim.x;
    int warp_id = tid / WARP_SIZE;
    int lane_id = tid % WARP_SIZE;
    int num_warps = num_threads / WARP_SIZE;

    __shared__ float shared_max[BLOCK_SIZE / WARP_SIZE];
    __shared__ float shared_sum[BLOCK_SIZE / WARP_SIZE];

    // First pass: compute GELU values and find max
    float local_max = -3.402823466e+38f;

    for (int i = tid; i < vec_features; i += num_threads) {
        float4 v = row_in[i];
        float g0 = gelu(v.x);
        float g1 = gelu(v.y);
        float g2 = gelu(v.z);
        float g3 = gelu(v.w);

        local_max = fmaxf(local_max, fmaxf(fmaxf(g0, g1), fmaxf(g2, g3)));

        // Store GELU values temporarily in output
        row_out[i] = make_float4(g0, g1, g2, g3);
    }

    // Warp reduce max
    local_max = warp_reduce_max(local_max);
    if (lane_id == 0) {
        shared_max[warp_id] = local_max;
    }
    __syncthreads();

    if (warp_id == 0) {
        float val = (lane_id < num_warps) ? shared_max[lane_id] : -3.402823466e+38f;
        val = warp_reduce_max(val);
        if (lane_id == 0) {
            shared_max[0] = val;
        }
    }
    __syncthreads();

    float row_max = shared_max[0];

    // Second pass: compute exp values and sum using stored GELU values
    float local_sum = 0.0f;

    for (int i = tid; i < vec_features; i += num_threads) {
        float4 gelu_val = row_out[i];
        float e0 = expf(gelu_val.x - row_max);
        float e1 = expf(gelu_val.y - row_max);
        float e2 = expf(gelu_val.z - row_max);
        float e3 = expf(gelu_val.w - row_max);

        local_sum += e0 + e1 + e2 + e3;

        row_out[i] = make_float4(e0, e1, e2, e3);
    }

    // Warp reduce sum
    local_sum = warp_reduce_sum(local_sum);
    if (lane_id == 0) {
        shared_sum[warp_id] = local_sum;
    }
    __syncthreads();

    if (warp_id == 0) {
        float val = (lane_id < num_warps) ? shared_sum[lane_id] : 0.0f;
        val = warp_reduce_sum(val);
        if (lane_id == 0) {
            shared_sum[0] = val;
        }
    }
    __syncthreads();

    float inv_sum = 1.0f / shared_sum[0];

    // Third pass: normalize
    for (int i = tid; i < vec_features; i += num_threads) {
        float4 v = row_out[i];
        row_out[i] = make_float4(v.x * inv_sum, v.y * inv_sum, v.z * inv_sum, v.w * inv_sum);
    }
}

