        val.x *= combined_factor;
        val.y *= combined_factor;
        val.z *= combined_factor;
        val.w *= combined_factor;

        // Store back
        *ptr = val;
    } else {
        // Handle remainder
        for (int i = idx; i < size && i < idx + 4; i++) {
            data[i] *= combined_factor;
        }
    }
}

